function slugify(title) {
  if (typeof title !== 'string') {
    return '';
  }

  return title
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9 -]/g, '')
    .replace(/[\s-]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

module.exports = { slugify };

